package com.medicine.reminder.service;
import com.medicine.reminder.dto.*; import com.medicine.reminder.model.*; import com.medicine.reminder.repository.*; import com.medicine.reminder.util.JwtUtil; import org.springframework.http.HttpStatus; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@Service public class AuthService { private final UserRepository users; private final PasswordEncoder encoder; private final JwtUtil jwt; public AuthService(UserRepository u,PasswordEncoder e,JwtUtil j){users=u;encoder=e;jwt=j;}
 public void register(RegisterRequest r){if(users.existsByUsername(r.getUsername())||users.existsByEmail(r.getEmail()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Username or email is already registered");User u=new User();u.setUsername(r.getUsername().trim());u.setEmail(r.getEmail().trim().toLowerCase());u.setPassword(encoder.encode(r.getPassword()));users.save(u);}
 public Map<String,String> login(LoginRequest r){User u=users.findByUsername(r.getUsername()).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid username or password"));if(!encoder.matches(r.getPassword(),u.getPassword()))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid username or password");return Map.of("token",jwt.generate(u.getUsername(),u.getId()),"username",u.getUsername());}
}
